// ===========================================================================
// 6. Host reads memory used by a stream it never synced on
// ===========================================================================

// one host thread, two streams, only one of them synced
TEST_F(SM_Tests, host_read_of_unsynced_stream_memory) {
  constexpr std::size_t N_DW = 10u, N_HR_BAD = 3u, N_HR_OK = 6u;
  auto tid = spawn_host_thread();
  auto s2 = spawn_device_stream();
  auto mem_a = malloc_event(tid);                   // written on the default stream (never synced)
  auto mem_b = malloc_event(tid);                   // written on s2 (synced)
  host_write_event(tid, mem_a);
  host_write_event(tid, mem_b);

  auto j1 = launch_event(tid);                      // default stream (never synced)
  auto j2 = launch_event(tid, s2);
  auto sloc_dw_a = generate_metadata();
  auto sloc_dw_b = generate_metadata();
  for (std::size_t i=0; i<N_DW; ++i) {
    device_write_event(j1, mem_a, 0u, sloc_dw_a);
    device_write_event(j2, mem_b, 0u, sloc_dw_b);
  }
  device_job_completes_event(j1);
  device_job_completes_event(j2);

  sync_event(tid, s2);                              // the default stream is intentionally NOT synced
  auto sloc1 = generate_metadata();
  auto sloc2 = generate_metadata();
  for (std::size_t i=0; i<N_HR_OK; ++i)  host_read_event(tid, mem_b, 0u, sloc1);
  for (std::size_t i=0; i<N_HR_BAD; ++i) host_read_event(tid, mem_a, 0u, sloc2);
  free_event(tid, mem_b);
  free_event(tid, mem_a);

  run();
  auto iErrs = get_internal_errors();
  ASSERT_FALSE(iErrs) << iErrs;

  EXPECT_FALSE(any_true_race());
  EXPECT_GE(status_count(Status::POS_RACE_HR_DW), 1u);
  EXPECT_EQ(status_count_all(), 
            status_count(Status::POS_RACE_HR_DW)    //NOTE: first instance will be of the pos race type
            + status_count(Status::UNPROTECTED_HR)  //      all others will be seen as unprotected type
          ) << "reads of mem_b must stay clean";
}

// sync is per (host thread, stream): t1 syncing does not protect t2
TEST_F(SM_Tests, sync_on_other_host_thread_does_not_protect) {
  constexpr std::size_t N_DW = 9u, N_HR_T2 = 4u, N_HR_T1 = 5u;
  auto t1 = spawn_host_thread();
  auto mem = malloc_event(t1);
  host_write_event(t1, mem);

  auto jid = launch_event(t1);
  auto sloc1 = generate_metadata();
  for (std::size_t i=0; i<N_DW; ++i) device_write_event(jid, mem, 0u, sloc1);
  device_job_completes_event(jid);
  sync_event(t1);

  auto sloc2 = generate_metadata();
  for (std::size_t i=0; i<N_HR_T1; ++i) host_read_event(t1, mem, 0u, sloc2);   // fine

  auto t2 = spawn_host_thread(); // new host thread starts work after sync
  auto sloc3 = generate_metadata();
  for (std::size_t i=0; i<N_HR_T2; ++i) host_read_event(t2, mem, 0u, sloc3);   // t2 never synced
  free_event(t1, mem);

  run();
  auto iErrs = get_internal_errors();
  ASSERT_FALSE(iErrs) << iErrs;

  EXPECT_FALSE(any_true_race());
  EXPECT_GE(status_count(Status::POS_RACE_HR_DW) + status_count(Status::UNPROTECTED_HR), 1u);
  //NOTE: since the second thread has no relationship to the device stream, it's reads will just
  //      be considered unprotected and not a possible race.  It would have needed to have done something
  //      with the device stream at some point to be of a possible race type.
}


// ===========================================================================
// Complications
// ===========================================================================

// many rounds of ping-pong on one address, all correctly synced; then one
// final round that skips the sync
TEST_F(SM_Tests, ping_pong_same_address_clean_then_one_unsynced_round) {
  constexpr int CLEAN_ROUNDS = 10;
  constexpr std::size_t DW_PER_ROUND = 2u;
  auto tid = spawn_host_thread();
  auto stream = spawn_device_stream();
  auto mem = malloc_event(tid);
  host_write_event(tid, mem);

  auto sloc_launch = generate_metadata();
  auto sloc_dr     = generate_metadata();
  auto sloc_dw     = generate_metadata();
  auto sloc_sync   = generate_metadata();
  auto sloc_hr     = generate_metadata();
  auto sloc_hw     = generate_metadata();
  for (int r=0; r<CLEAN_ROUNDS; ++r) {
    auto jid = launch_event(tid, stream, sloc_launch);
    for (int i=0; i<3; ++i) device_read_event(jid, mem, 0u, sloc_dr);
    for (std::size_t i=0; i<DW_PER_ROUND; ++i) device_write_event(jid, mem, 0u, sloc_dw);
    device_job_completes_event(jid);
    sync_event(tid, stream, sloc_sync);
    host_read_event(tid, mem, 0u, sloc_hr);
    host_write_event(tid, mem, 0u, sloc_hw);
  }
  run();
  auto iErrs = get_internal_errors();
  ASSERT_FALSE(iErrs) << iErrs;
  EXPECT_FALSE(any_issues()) << "clean rounds must not report anything";
  // NOTE: run() may be called again after appending more events
  auto jid = launch_event(tid, stream);
  device_read_event(jid, mem);
  auto sloc1 = generate_metadata();
  for (std::size_t i=0; i<DW_PER_ROUND; ++i) device_write_event(jid, mem, 0u, sloc1);
  device_job_completes_event(jid);
  host_read_event(tid, mem);                        // no sync -> possible race
  sync_event(tid, stream);
  free_event(tid, mem);

  run();
  iErrs = get_internal_errors();
  ASSERT_FALSE(iErrs) << iErrs;

  EXPECT_FALSE(any_true_race());
  EXPECT_GE(status_count(Status::POS_RACE_HR_DW), 1u);
}

// several jobs per stream: same-stream jobs are ordered, so job2 reading job1's
// output is fine as long as the host syncs before touching it
TEST_F(SM_Tests, multiple_jobs_per_stream_clean) {
  auto tid = spawn_host_thread();
  auto s1 = spawn_device_stream();
  auto a = malloc_event(tid);
  auto b = malloc_event(tid);
  host_write_event(tid, a);
  host_write_event(tid, b);

  auto sloc_launch0 = generate_metadata();
  auto sloc_launch1 = generate_metadata();
  auto sloc_dr_a = generate_metadata();
  auto sloc_dw_a = generate_metadata();
  auto sloc_dr_b = generate_metadata();
  auto sloc_dw_b = generate_metadata();
  auto sloc_sync0 = generate_metadata();
  auto sloc_sync1 = generate_metadata();
  auto sloc_hr_a = generate_metadata();
  auto sloc_hr_b = generate_metadata();
  auto sloc_hw_a = generate_metadata();
  auto sloc_hw_b = generate_metadata();
  for (int round=0; round<4; ++round) {
    auto j0 = launch_event(tid, nullptr, sloc_launch0);   // default stream;
    for (int i=0; i<8; ++i) {
      device_read_event(j0, a, 0u, sloc_dr_a);
      device_write_event(j0, a, 0u, sloc_dw_a);
    }
    device_job_completes_event(j0);

    auto j1 = launch_event(tid, s1, sloc_launch1);
    for (int i=0; i<8; ++i) {
      device_read_event(j1, b, 0u, sloc_dr_b);
      device_write_event(j1, b, 0u, sloc_dw_b);
    }
    device_job_completes_event(j1);

    sync_event(tid, nullptr, sloc_sync0);
    sync_event(tid, s1, sloc_sync1);
    host_read_event(tid, a, 0u, sloc_hr_a);
    host_read_event(tid, b, 0u, sloc_hr_b);
    host_write_event(tid, a, 0u, sloc_hw_a);
    host_write_event(tid, b, 0u, sloc_hw_b);
  }
  free_event(tid, a);
  free_event(tid, b);

  run();
  auto iErrs = get_internal_errors();
  ASSERT_FALSE(iErrs) << iErrs;

  EXPECT_FALSE(any_issues());
  EXPECT_EQ(status_count_all(), 0u) << get_results();
}

// 3 host threads, 3 streams, 4 independent regions each exercising a different status
TEST_F(SM_Tests, multi_thread_multi_stream_mixed_statuses) {
  constexpr std::size_t N_DW_P = 6u, N_HR_P = 3u;              // possible race region
  constexpr std::size_t N_DR_T_BEFORE = 4u, N_DR_T_AFTER = 4u, N_HW_T = 2u;  // true race region
  constexpr std::size_t N_UNINIT = 3u;                         // uninit region

  auto t0 = spawn_host_thread();
  auto t1 = spawn_host_thread();
  auto t2 = spawn_host_thread();
  auto s1 = spawn_device_stream();
  auto s2 = spawn_device_stream();

  auto clean = malloc_event(t0);
  auto poss  = malloc_event(t1);
  auto truer = malloc_event(t2);
  auto uninit = malloc_event(t1);

  host_write_event(t0, clean);
  host_write_event(t1, poss);
  host_write_event(t2, truer);

  // region 1: clean (t0 / default stream)
  auto jc = launch_event(t0);
  auto sloc1 = generate_metadata();
  for (int i=0; i<10; ++i) device_read_event(jc, clean, 0u, sloc1);
  device_write_event(jc, clean);
  device_job_completes_event(jc);
  sync_event(t0);
  host_read_event(t0, clean);

  run();
  auto iErrs = get_internal_errors();
  ASSERT_FALSE(iErrs) << iErrs;

  EXPECT_EQ(status_count_all(), 0u) 
    << "the clean region must contribute nothing" 
    << get_results();
  //NOTE: moveing the clean region test here than continuing is possible and better way to do this test.

  // region 2: possible race (t1 launches on s1, job finishes, t2 reads w/o ever syncing s1)
  auto jp = launch_event(t1, s1);
  auto sloc2 = generate_metadata();
  for (std::size_t i=0; i<N_DW_P; ++i) device_write_event(jp, poss, 0u, sloc2);
  device_job_completes_event(jp);
  auto sloc3 = generate_metadata();
  for (std::size_t i=0; i<N_HR_P; ++i) host_read_event(t2, poss, 0u, sloc3);

  // region 3: true race (t2 launches on s2, t0 writes while the job is still running)
  auto jt = launch_event(t2, s2);
  auto sloc4 = generate_metadata();
  for (std::size_t i=0; i<N_DR_T_BEFORE; ++i) device_read_event(jt, truer, 0u, sloc4);
  auto sloc5 = generate_metadata();
  for (std::size_t i=0; i<N_HW_T; ++i) host_write_event(t0, truer, 0u, sloc5);
  auto sloc6 = generate_metadata();
  for (std::size_t i=0; i<N_DR_T_AFTER; ++i) device_read_event(jt, truer, 0u, sloc6);
  device_job_completes_event(jt);

  // region 4: host reads memory nobody ever wrote
  auto sloc7 = generate_metadata();
  for (std::size_t i=0; i<N_UNINIT; ++i) host_read_event(t1, uninit, 0u, sloc7);

  sync_event(t1, s1);
  sync_event(t2, s2);
  free_event(t0, clean);
  free_event(t1, poss);
  free_event(t2, truer);
  free_event(t1, uninit);

  run();
  auto iErrs2 = get_internal_errors();
  ASSERT_FALSE(iErrs2) << iErrs2;

  EXPECT_TRUE(any_true_race()) << get_results();
  EXPECT_GE(status_count(Status::POS_RACE_HR_DW), 1u);
  EXPECT_GE(status_count(Status::RACE_DR_HW), 1u);
  EXPECT_GE(status_count(Status::READ_UNINIT_H), 1u);
  EXPECT_EQ(status_count(Status::READ_UNINIT_D), 0u);
  // EXPECT_EQ(status_count_all(),
  //           status_count(Status::POS_RACE_HR_DW) + status_count(Status::UNPROTECTED_HR)
  //         + status_count(Status::RACE_DR_HW)
  //         + status_count(Status::POS_RACE_DR_HW) + status_count(Status::UNPROTECTED_HW)
  //         + status_count(Status::READ_UNINIT_H)) << "the clean region must contribute nothing";
  //NOTE: this test is meaningless, because of the fact that the unprotected result type can occur
  //      in the place of a possible race result type. Due to limitations in the how we store previous
  //      memory events in a single interval map.
}


// ===========================================================================
// Default-stream combinations
// ===========================================================================

// two host threads, each on the default stream with its own memory, each syncing the default
// stream before reading its own data. Clean in both default-stream modes.
TEST_F(SM_Tests, two_threads_default_streams_own_memory_clean) {
  reset_sm();
  auto t1 = spawn_host_thread();
  auto t2 = spawn_host_thread();
  auto mem1 = malloc_event(t1);
  auto mem2 = malloc_event(t2);
  host_write_event(t1, mem1);
  host_write_event(t2, mem2);

  auto j1 = launch_event(t1);
  auto sloc1 = generate_metadata();
  for (int i=0; i<10; ++i) device_read_event(j1, mem1, 0u, sloc1);
  auto sloc2 = generate_metadata();
  for (int i=0; i<4; ++i) device_write_event(j1, mem1, 0u, sloc2);
  device_job_completes_event(j1);

  auto j2 = launch_event(t2);
  auto sloc3 = generate_metadata();
  for (int i=0; i<10; ++i) device_read_event(j2, mem2, 0u, sloc3);
  auto sloc4 = generate_metadata();
  for (int i=0; i<4; ++i) device_write_event(j2, mem2, 0u, sloc4);
  device_job_completes_event(j2);

  sync_event(t1);
  sync_event(t2);
  host_read_event(t1, mem1);
  host_read_event(t2, mem2);
  free_event(t1, mem1);
  free_event(t2, mem2);

  run();
  auto iErrs = get_internal_errors();
  ASSERT_FALSE(iErrs) << iErrs;

  EXPECT_FALSE(any_issues()) << "t1: 0x" << std::hex << t1 
                             << "\nt2: 0x" << t2 << std::dec;
  EXPECT_EQ(status_count_all(), 0u) << get_results();
}

#ifdef SM_TEST_DEFAULT_STREAM_LEGACY
// legacy mode: the default stream is shared by every host thread, so a sync of it by a thread
// that never launched anything still covers t1's kernel -> t2's read is protected.
// NOTE: assumes the SM keys the zone on the shared default stream rather than on the launcher.
TEST_F(SM_Tests, legacy_default_stream_sync_by_other_thread_protects) {
  ASSERT_TRUE(DEFAULT_STREAM_BEHAVIOR() == hipStreamLegacy_ull) 
    << "backend is not using legacy default stream behavior";
  auto t1 = spawn_host_thread();
  auto t2 = spawn_host_thread();
  auto mem = malloc_event(t1);
  host_write_event(t1, mem);

  auto jid = launch_event(t1);                      // default stream (shared)
  auto sloc1 = generate_metadata();
  for (int i=0; i<10; ++i) device_write_event(jid, mem, 0u, sloc1);
  device_job_completes_event(jid);

  sync_event(t2);                                   // other thread syncs the shared default stream
  auto sloc2 = generate_metadata();
  for (int i=0; i<4; ++i) host_read_event(t2, mem, 0u, sloc2);
  free_event(t2, mem);

  run();
  auto iErrs = get_internal_errors();
  ASSERT_FALSE(iErrs) << iErrs;

  EXPECT_FALSE(any_issues());
  EXPECT_EQ(status_count_all(), 0u) << get_results();
}
#endif //? SM_TEST_DEFAULT_STREAM_LEGACY

#ifdef SM_TEST_DEFAULT_STREAM_PER_THREAD
// per-thread mode: each host thread's default stream is its own, so t2 syncing ITS default
// stream says nothing about t1's kernel -> t2's read is unprotected.
TEST_F(SM_Tests, per_thread_default_stream_sync_by_other_thread_does_not_protect) {
  ASSERT_TRUE(DEFAULT_STREAM_BEHAVIOR() == hipStreamPerThread_ull) 
    << "backend is not using per-thread default stream behavior";
  auto t1 = spawn_host_thread();
  auto t2 = spawn_host_thread();
  auto mem = malloc_event(t1);
  host_write_event(t1, mem);

  auto jid = launch_event(t1);                      // t1's own default stream
  auto sloc1 = generate_metadata();
  for (int i=0; i<10; ++i) device_write_event(jid, mem, 0u, sloc1);
  device_job_completes_event(jid);

  sync_event(t2);                                   // t2's own, unrelated default stream
  auto sloc2 = generate_metadata();
  for (int i=0; i<4; ++i) host_read_event(t2, mem, 0u, sloc2);
  free_event(t2, mem);

  run();
  auto iErrs = get_internal_errors();
  ASSERT_FALSE(iErrs) << iErrs;

  EXPECT_FALSE(any_true_race());
  EXPECT_GE(status_count(Status::POS_RACE_HR_DW) + status_count(Status::UNPROTECTED_HR), 1u) << get_results();
}
#endif //? SM_TEST_DEFAULT_STREAM_PER_THREAD

